/** Providers with live API sync (TallyPrime, Zoho Books, QuickBooks). */
export const ACCOUNTING_API_SYNC_PROVIDER_IDS = ['tally', 'zoho', 'quickbooks'] as const;

/**
 * Providers whose self-serve Connect UI is hidden.
 * TallyPrime HTTP API is only reachable when the backend runs on the same host as Tally (localhost).
 */
export const ACCOUNTING_LOCALHOST_ONLY_CONNECT_PROVIDER_IDS = ['tally'] as const;

/** Providers supported via file import only — no live API sync. */
export const ACCOUNTING_IMPORT_ONLY_PROVIDER_IDS = [
  'busy',
  'marg',
  'vyapar',
  'mybillbook',
  'khatabook',
  'erpnext',
  'odoo',
  'clear',
  'profitbooks',
  'hostbooks',
] as const;

export const ACCOUNTING_API_SYNC_LABEL = 'TallyPrime, Zoho Books, and QuickBooks';

export const isAccountingApiSyncProvider = (providerId: string): boolean =>
  ACCOUNTING_API_SYNC_PROVIDER_IDS.includes(providerId as (typeof ACCOUNTING_API_SYNC_PROVIDER_IDS)[number]);

/** True when Connect/Manage is not offered because the API is localhost-only. */
export const isLocalhostOnlyConnectProvider = (providerId: string): boolean =>
  ACCOUNTING_LOCALHOST_ONLY_CONNECT_PROVIDER_IDS.includes(
    providerId as (typeof ACCOUNTING_LOCALHOST_ONLY_CONNECT_PROVIDER_IDS)[number]
  );
